use verus::prelude::*;

verus! {

    fn conditional_average(
        vals_1: &Vec<u64>,
        vals_2: &Vec<u64>,
        conds_1: &Vec<bool>,
        conds_2: &Vec<bool>,
        avgs: &mut Vec<u64>
    )
        requires
            vals_1.len() == vals_2.len(),
            vals_1.len() == conds_1.len(),
            conds_1.len() == conds_2.len(),
        requires
            forall|i: usize| i < vals_1.len() ==>
                vals_1[i] < 1000 && vals_2[i] < 1000,
        requires
            forall|i: usize| i < conds_1.len() ==>
                conds_1[i] || conds_2[i],
        ensures
            avgs@ == conditional_average_spec(
                vals_1@, vals_2@, conds_1@, conds_2@
            )
    {
        let n = vals_1.len();
        // Start with an empty output.
        avgs.clear();

        let mut i: usize = 0;
        // Process one index per loop iteration.
        while i < n
            invariant
                // i never exceeds n
                i <= n,
            invariant
                // for every already‐processed j < i,
                // we have pushed exactly the spec‐value
                forall|j: usize| j < i ==>
                    avgs[j] ==
                        if conds_1[j] && conds_2[j] {
                            (vals_1[j] + vals_2[j]) / 2
                        } else if conds_1[j] {
                            vals_1[j]
                        } else {
                            vals_2[j]
                        },
            decreases
                // measure to prove termination
                n - i
        {
            let v1 = vals_1[i];
            let v2 = vals_2[i];
            let c1 = conds_1[i];
            let c2 = conds_2[i];

            let x = if c1 && c2 {
                // both true: average
                (v1 + v2) / 2
            } else if c1 {
                // only first true
                v1
            } else {
                // only second true
                v2
            };

            avgs.push(x);
            i += 1;
        }
    }

}